FD=formula('τ=M(q)q̈+C(q,q̇)+G(q); q̈=M(q)⁻¹[τ−C(q,q̇)−G(q)]',{'q':'n×1 joint angle vector','q̇,q̈':'joint angular velocity and acceleration vectors','M':'n×n symmetric inertia matrix','C':'n×1 Coriolis/centrifugal torque vector, already including velocity products','G':'n×1 gravity-compensation torque vector','τ':'n×1 applied joint torque vector','n':'number of revolute joints'},{'q':'rad','q̇':'rad/s','q̈':'rad/s²','M':'kg·m²','C,G,τ':'N·m','n':'dimensionless count'},['Nominal rigid revolute-joint model; no unlisted friction/contact term; M invertible for forward dynamics.'])
