FC=formula('h=m2 l1 l2 sin(q2); C1=−h q̇2²−2h q̇1q̇2; C2=h q̇1²',{'h':'configuration-dependent coupling coefficient','m2':'distal point mass','l1,l2':'link lengths','q2':'relative elbow angle','q̇1,q̇2':'shoulder/elbow joint angular velocities','C1,C2':'velocity-product torque components'},{'h':'kg·m²','m2':'kg','l1,l2':'m','q2':'rad','q̇1,q̇2':'rad/s','C1,C2':'N·m'},['Planar massless-link, tip-point-mass model; angles follow source diagram.'])
FG=formula('G1=(m1+m2)g l1 cos(q1)+m2 g l2 cos(q1+q2); G2=m2 g l2 cos(q1+q2)',{'m1,m2':'point masses at first and second link tips','l1,l2':'link lengths','g':'positive gravitational acceleration magnitude','q1':'first-link angle from horizontal','q2':'relative elbow angle','G1,G2':'gravity-compensation torques'},{'m1,m2':'kg','l1,l2':'m','g':'m/s²','q1,q2':'rad','G1,G2':'N·m'},['Gravity acts downward; potential is measured from an arbitrary height reference; massless links with tip masses.'])
FK=formula('K=½q̇ᵀH(q)q̇; V=(m1+m2)g l1 sin(q1)+m2 g l2 sin(q1+q2); G=∇qV',{'K':'physical kinetic energy','V':'gravitational potential energy, up to a constant','H':'2×2 inertia matrix, equal to M in the nominal model','q':'(q1,q2) joint-angle vector','q̇':'joint angular velocity vector','q1':'shoulder angle from horizontal','q2':'relative elbow angle','m1,m2':'point masses at link tips','l1,l2':'link lengths','g':'gravity magnitude','G':'gravity-compensation torque vector'},{'K,V':'J','H':'kg·m²','q,q1,q2':'rad','q̇':'rad/s','m1,m2':'kg','l1,l2':'m','g':'m/s²','G':'N·m'},['Massless planar links with point tip masses; physical K includes one-half.'])
FE=formula('L=K−V; τ=d/dt(∂L/∂q̇)−∂L/∂q=Hq̈+Ḣq̇−∇qK+∇qV; Ḣ=Σk(∂H/∂qk)q̇k',{'L':'Lagrangian','K':'physical kinetic energy ½q̇ᵀHq̇','V':'potential energy','q,q̇,q̈':'joint angles, velocities and accelerations','H':'symmetric inertia matrix','Ḣ':'total time derivative of H along the motion','qk,q̇k':'joint k angle and velocity','τ':'required generalized joint torque','∇q':'gradient with respect to configuration while holding velocity fixed'},{'L,K,V':'J','q,qk':'rad','q̇,q̇k':'rad/s','q̈':'rad/s²','H':'kg·m²','Ḣ':'kg·m²/s','τ':'N·m'},['Time-invariant nominal conservative mechanical model; any other generalized forces must be added explicitly. Physical kinetic energy includes one-half, so its gradient is not halved again.'])
