def add(refs,key,title,stem,pairs,typ='conceptual',difficulty='easy',forms=None,steps=None,assumptions=None,conflict=None,evidence=None):
 # A reference is (physical page, exact content kind, item-level locator[,role]).
 shift=len(b.questions)%4;pairs=pairs[shift:]+pairs[:shift];correct=(-shift)%4
 why=pairs[correct][1]
 q=b.add([r[0] for r in refs],key,title,stem,[x[0] for x in pairs],correct,why,[x[1] for x in pairs],typ=typ,difficulty=difficulty,assumptions=assumptions,steps=steps,formulas=forms,conflict=conflict)
 for c,r in zip(q['citations'],refs):
  c['kind']=r[1];c['locator']=f'Lecture L55, physical PDF page {r[0]}, printed footer {r[0]-1744}: {r[2]}'
  c['role']=r[3] if len(r)>3 else ('conflict' if conflict else 'premise' if typ in ['scenario','numerical','derivation'] else 'explicit')
 if conflict:
  q['conflictResolution'].update(sourceId='lectures',sourceSha256=SHA,physicalPages=[c['physicalPage'] for c in q['citations'] if c['role']=='conflict']);issues.append({'questionId':q['id'],'sourceClaim':conflict,'qualification':why,'physicalPages':q['conflictResolution']['physicalPages']})
 if evidence:q['primaryEvidence']=[dict(primary[x],checkedAt='2026-10-19T23:56:42+00:00') for x in evidence]
 q['difficultyRationale']='Direct source distinction or one short specified operation.' if difficulty=='easy' else 'Combines multiple supplied conditions, formula operations or code conventions.' if difficulty=='medium' else 'Integrated multistage dynamics or derivative calculation.'
 b.save();return q
