add([(1755,'equation','Symmetric mass matrix and its entries.'),(1758,'code','Unit-parameter mass matrix.')],'mass-spd','Inertia definiteness','For the source unit masses and lengths, M=[[3+2cos q2,1+cos q2],[1+cos q2,1]]. What is its determinant and conclusion?', [('2−cos²q2, which is at least 1; M is positive definite.','The determinant is positive and M22=1>0, so this symmetric 2×2 matrix is positive definite.'),('1−cos²q2, so it becomes singular at q2=0.','This drops one constant term from the determinant.'),('2+cos²q2, so its off-diagonal coupling vanishes.','The determinant sign is wrong, and determinant alone does not make coupling zero.'),('3+2cos q2, obtained by ignoring the off-diagonal product.','The determinant must subtract (1+cos q2)² from the diagonal product.')],typ='derivation',difficulty='medium',forms=[FM,formula('det([[a,b],[b,d]])=ad−b²',{'a,b,d':'entries of a real symmetric 2×2 inertia matrix','det':'determinant'},{'a,b,d':'kg·m²','det':'kg²·m⁴'},['For positive definiteness, d>0 and ad−b²>0 suffice.'])],steps=['det=(3+2c)−(1+c)²=2−c², where c=cos q2.','Since c²≤1, determinant≥1 and M22=1.'])
