add([(1756,'equation','Gravity vector for horizontal-angle convention.')],'gravity','Horizontal and vertical gravity','With the source unit masses/lengths and g=9.81 m/s², what gravity torque is needed at rest for q1=q2=0?', [('(29.43,9.81) N·m.','Both links are horizontal; G1=(2+1)g and G2=g.'),('(0,0) N·m.','That would apply to a vertically aligned configuration, not the horizontal one.'),('(19.62,9.81) N·m.','The shoulder term omits the distal link’s additional moment arm.'),('(−29.43,−9.81) N·m.','These are the opposite signs from the defined gravity-compensation torques.')],typ='numerical',forms=[FG],steps=['Use cos0=1 in both gravity terms.','At rest with zero acceleration and no other load, τ=G.'])
add([(1756,'equation','Full torque rows and velocity/gravity terms.'),(1758,'code','Unit-parameter inverse dynamics implementation.')],'full-torque','Integrated 2R inverse dynamics','For the source unit parameters and g=9.81, take q1=0, q2=π/2, q̇=(2,−1), and q̈=(1,−2), in radians and seconds. What torque follows?', [('(23.62,3) N·m.','M=[[3,1],[1,1]], Mq̈=(1,−1), C=(3,4), G=(19.62,0); their sum is(23.62,3).'),('(20.62,−1) N·m.','This omits C.'),('(4,3) N·m.','This omits G.'),('(25.62,2) N·m.','This drops off-diagonal inertia terms before adding C and G.')],typ='numerical',difficulty='medium',forms=[FM,FC,FG,FD],steps=['At q2=π/2, cosine is 0 and sine is 1.','Form M=[[3,1],[1,1]], then Mq̈=(1,−1).','Compute C=(3,4) and G=(19.62,0).','Sum all three vectors.'],assumptions=['Source nominal point-mass system, no friction or additional contact torque.'])
add([(1757,'statement','Ordered feature and torque vectors.'),(1759,'code','X and Y column_stack statements.')],'feature-order','Feature ordering at prediction','The trained X columns are [q1,q2,q̇1,q̇2,q̈1,q̈2]. For an added state q=(1,2), q̇=(3,4), q̈=(5,6), which prediction row preserves this convention?', [('(1,2,3,4,5,6).','The code groups the two positions, then two velocities, then two accelerations.'),('(1,3,5,2,4,6).','This interleaves joint triples, a different ordering from the fitted code.'),('(5,6,3,4,1,2).','This reverses the acceleration and position groups.'),('(1,2,5,6,3,4).','This swaps the velocity and acceleration groups.')],typ='scenario')
add([(1757,'statement','Angle, velocity and acceleration sampling ranges.'),(1759,'code','Independent uniform samples for six feature columns.')],'sampling','Sampled state domain','Which added state is inside all the source sampling ranges q∈[−π,π], q̇∈[−2π,2π], q̈∈[−10,10] componentwise?', [('q=(1,−2), q̇=(4,−5), q̈=(8,−9).','All coordinates satisfy their respective angle, velocity and acceleration bounds.'),('q=(4,−2), q̇=(4,−5), q̈=(8,−9).','The first angle exceeds π.'),('q=(1,−2), q̇=(7,−5), q̈=(8,−9).','The first velocity exceeds 2π.'),('q=(1,−2), q̇=(4,−5), q̈=(11,−9).','The first acceleration exceeds 10.')],typ='scenario',assumptions=['Angles in rad, velocities in rad/s and accelerations in rad/s². These sampling limits do not certify physical safety.'])
add([(1757,'statement','Random sampling description.'),(1759,'code','Independent uniform coordinate draws.')],'sampling-scope','What uniform sampling covers','What does the source’s independent uniform joint-coordinate sampling establish?', [('Uniform marginals in the specified coordinate intervals, not uniform Cartesian workspace coverage or a time-consistent trajectory.','A nonlinear kinematic map changes spatial density, and unrelated state tuples are not an integrated motion.'),('Uniform Cartesian endpoint density because every joint angle interval is sampled uniformly.','Nonlinear coordinate changes generally do not preserve uniform density.'),('A physically integrated trajectory because velocities and accelerations are included in each row.','Independently drawn derivatives need not connect successive rows.'),('Equally spaced coordinate grids because np.random.uniform covers an interval.','Random uniform draws are not deterministic evenly spaced grids.')],typ='scenario',conflict='The dataset description broadly calls random joint-coordinate samples uniform workspace coverage; the printed code samples joint variables independently.')
add([(1759,'code','N, column_stack and train_test_split statements.')],'array-shapes','MLP dataset dimensions','After generating 50,000 states and splitting with test_size=0.1, what are the training input and test target shapes?', [('(45000,6) and (5000,2).','Six ordered features and two torque targets are split by rows in a 90:10 ratio.'),('(45000,2) and (5000,6).','This reverses feature and target widths.'),('(5000,6) and (45000,2).','This swaps the training and test row counts.'),('(45000,6) and (5000,1).','The regressor has two torque outputs, not a single combined target.')],typ='code',steps=['Training rows=0.9×50000=45000; test rows=5000.','X has six columns and Y has two.'])
add([(1759,'code','Unseeded np.random.uniform calls and seeded train_test_split.'),(1760,'code','MLPRegressor random_state=42.')],'reproducibility','Which randomness is controlled','Which statement accurately describes reproducibility of the printed MLP example?', [('The split and MLP have fixed random_state values, but the earlier NumPy-generated dataset has no displayed seed.','Later seeds do not retroactively seed the preceding np.random.uniform draws.'),('The split seed also fixes all earlier random torque-label inputs.','train_test_split does not seed already executed dataset generation.'),('The network seed guarantees identical results across any changed input dataset.','Fixed model randomness cannot make changed training data identical.'),('No randomness is controlled because a NumPy seed is absent.','The source does explicitly control split and estimator randomness.')],typ='code',evidence=['mlp'])
add([(1760,'code','Pipeline StandardScaler followed by MLPRegressor and fit(X_tr,Y_tr).')],'scaler-fit','Leakage-free scaling','How should this printed pipeline use training and test data?', [('Fit scaler statistics on X_tr, fit the regressor on scaled X_tr, and reuse those statistics for X_te.','Pipeline fitting estimates the preprocessing from the training input supplied to fit.'),('Fit the scaler on concatenated X_tr and X_te before evaluating X_te.','This lets held-out inputs influence fitted preprocessing.'),('Fit a fresh scaler independently on X_te before prediction.','That changes the coordinate transformation seen by the trained network.'),('Scale Y_tr with the input scaler because both arrays have the same number of rows.','Targets have two columns and are not transformed by this input pipeline.')],typ='code',evidence=['scaler'])
add([(1760,'code','StandardScaler input preprocessing.')],'standard-score','Scaling a feature','For an added training feature with mean μ=2 rad and standard deviation σ=4 rad, what transformed value does x=10 rad have under z=(x−μ)/σ?', [('2.','(10−2)/4=2.'),('3.','This adds the mean instead of subtracting it.'),('2.5.','This divides by σ without centering.'),('0.5.','This divides by the variance 16 instead of standard deviation 4.')],typ='numerical',forms=[formula('z=(x−μ)/σ',{'x':'input feature value','μ':'training-set feature mean','σ':'positive training-set feature standard deviation','z':'standardized feature'},{'x,μ,σ':'same feature units, here rad','z':'dimensionless'},['Use fitted training statistics; this example has nonzero variance.'])],steps=['Center to 8 rad and divide by 4 rad.'],evidence=['scaler'])
add([(1760,'code','StandardScaler input preprocessing.')],'zero-variance','Constant-feature qualification','If a training input feature is constant, how does StandardScaler qualify the phrase unit variance?', [('It cannot create unit variance; its scale factor is 1, and centering maps that training constant to zero.','A constant feature has zero variance, and the documented fallback avoids division by zero.'),('It inserts random noise until the feature variance becomes one.','StandardScaler does not inject noise.'),('It removes that feature and changes the network input width.','This transformer retains the feature column.'),('It divides by zero and necessarily makes all model training fail.','The documented scale-factor fallback prevents that division.')],typ='code',evidence=['scaler'])
add([(1760,'code','hidden_layer_sizes=(256,256,128), six inputs and two targets.'),(1759,'code','Input and target widths.')],'mlp-parameters','Large MLP parameter count','Assuming a bias at every non-input neuron, how many parameters are in the 6–256–256–128–2 fully connected regressor?', [('100738.','Layer counts are 1792, 65792, 32896 and 258; their sum is 100738.'),('100096.','This counts weights only and omits 642 biases.'),('100736.','This omits the two output biases.'),('101122.','This uses 256 rather than 128 in the final hidden layer’s bias and output calculation while retaining the earlier weight count.')],typ='numerical',difficulty='medium',forms=[FN],steps=['(6+1)×256=1792.','(256+1)×256=65792; (256+1)×128=32896.','(128+1)×2=258; add all four layer counts.'],assumptions=['Fully connected affine layers with the widths printed on the slide.'])
