add([(1761,'code','Per-joint RMSE expression and printed values.'),(1761,'equation','Adjacent error graphic lacks the averaging operation.','conflict')],'rmse-definition','Code versus metric drawing','Why should the printed code, rather than the simplified adjacent error drawing, define the dataset RMSE?', [('The code averages squared errors across test samples before taking a square root; the drawing omits that mean.','For one error, √(e²)=|e|. Dataset RMSE requires an explicit mean over samples.'),('The code uses the median squared error, whereas the drawing uses the mean.','np.mean is the arithmetic mean, not a median.'),('The code takes the square root before averaging absolute errors.','Its mean is inside the square root.'),('The drawing correctly defines dataset RMSE without a sample aggregation operation.','Multiple-sample RMSE cannot be specified by a lone squared error without aggregation.')],typ='code',forms=[FR],conflict='The adjacent RMSE graphic omits the mean over samples, while the code correctly uses np.sqrt(np.mean(error**2)).')
add([(1761,'code','Per-joint mean-square and square-root evaluation.')],'rmse-calc','Numerical RMSE','For added torque errors of 3 and 4 N·m on one joint, what is RMSE?', [('√12.5≈3.536 N·m.','The squared errors sum to 25; divide by two and take the square root.'),('3.5 N·m.','This is mean absolute error, not root mean square.'),('5 N·m.','This is the square root of the sum without dividing by the sample count.'),('12.5 N·m.','This leaves the mean square unsquare-rooted and assigns the wrong units.')],typ='numerical',forms=[FR],steps=['(3²+4²)/2=12.5 (N·m)².','Take the square root.'],assumptions=['Added two-sample example.'])
add([(1762,'figure','Two time plots, true blue and predicted red dashed torques.')],'mlp-plot','Reading the plotted fit','Which conclusion is supported by the plotted MLP torque curves alone?', [('Predicted torques track the displayed reference trajectory closely, with visible residual differences.','The plotted comparison supports a bounded observation about this displayed trajectory.'),('Every state in the six-dimensional sampling domain has the same small error as the shown trajectory.','A single trajectory does not cover the complete state domain.'),('The red curve is the training loss because it is dashed.','The legend identifies it as predicted torque, not loss.'),('The plotted fit proves closed-loop stability for arbitrary feedback gains.','A torque-fit plot does not supply a closed-loop stability argument.')],typ='diagram')
add([(1763,'statement','H(q), V(q), Euler–Lagrange torque and only-position-input claim.')],'subnet-inputs','Subnetwork input versus full dynamics','What is the proper scope of the statement that DeLaN needs only q as input?', [('The H and V subnetworks use q; the complete inverse-dynamics calculation also needs q̇ and q̈.','Configuration determines the learned energy functions, while kinetic and acceleration terms still depend on motion.'),('The torque is independent of velocity and acceleration once H and V are learned.','The displayed Euler–Lagrange calculation retains both dependencies.'),('q̇ and q̈ replace q as the sole inputs to the potential subnetwork.','The potential is a function of configuration in the stated model.'),('The analytical training torque can be generated from q alone for arbitrary motion.','The label generator explicitly takes velocities and accelerations too.')],conflict='The slide’s final only-q-input statement is overbroad if applied to the full torque predictor rather than its configuration subnetworks.')
add([(1763,'statement','Symmetric positive-definite H and scalar potential V.')],'energy-outputs','Physical output structure','For a two-joint conservative model, what structure is imposed on H(q) and V(q)?', [('H is a symmetric positive-definite 2×2 inertia matrix; V is a scalar potential.','This is the stated physical structure, in contrast to directly predicting two torques with an unconstrained MLP.'),('H is an arbitrary 2×2 matrix; V is a two-component torque vector.','This removes inertia symmetry/definiteness and confuses potential with its gradient.'),('H is a scalar kinetic energy; V is the 2×2 inverse mass matrix.','The names and mathematical roles are interchanged.'),('H is a 2×2 antisymmetric matrix; V is the velocity vector.','Those properties do not represent the stated mechanical energy functions.')],forms=[FK])
add([(1763,'statement','Positive-definite mass-matrix requirement.','premise')],'factor-spd','Added positive-definite factor example','An added factor construction uses H=LLᵀ with L=[[2,0],[1,1]] in compatible inertia square-root units. For q̇=(1,−1) rad/s, what are H and physical kinetic energy K?', [('H=[[4,2],[2,2]] kg·m² and K=1 J.','LLᵀ gives the stated matrix; Hq̇=(2,0) and K=½(1,−1)·(2,0)=1.'),('H=[[5,1],[1,1]] kg·m² and K=2 J.','This computes LᵀL instead of the specified LLᵀ.'),('H=[[4,2],[2,2]] kg·m² and K=2 J.','This omits the one-half in physical kinetic energy.'),('H=[[2,0],[1,1]] kg·m² and K=1 J.','This treats the nonsymmetric factor itself as the inertia matrix; the coincident energy at this velocity does not fix that structural error.')],typ='numerical',difficulty='medium',forms=[formula('K=½q̇ᵀHq̇',{'K':'physical kinetic energy','q̇':'two-component angular velocity vector','H':'symmetric positive-definite inertia matrix'},{'K':'J','q̇':'rad/s','H':'kg·m²'},['Added two-joint numerical example with compatible SI units.']),formula('H=LLᵀ',{'H':'symmetric inertia matrix','L':'nonsingular lower-triangular factor with positive diagonal','Lᵀ':'matrix transpose of L'},{'H':'kg·m²','L,Lᵀ':'kg^(1/2)·m'},['Added factor example; positive diagonal makes L nonsingular, ensuring positive definiteness.'])],steps=['Multiply L by its transpose.','Compute Hq̇, then halve q̇ᵀHq̇.'],assumptions=['Added numerical factor; the lecture does not give this exact matrix.'],evidence=['delan'])
add([(1764,'equation','Torque equation and bottom definition T=q̇ᵀHq̇.','conflict')],'doubled-energy','Energy normalization on the equation slide','The page defines T=q̇ᵀHq̇ but calls it kinetic energy. Which reading preserves the correct Euler–Lagrange torque?', [('Treat that T as twice physical kinetic energy, so −½∇T equals −∇K for K=½q̇ᵀHq̇.','The displayed torque can be consistent with the doubled definition, while the kinetic-energy label is inaccurate.'),('Treat T as physical kinetic energy and halve its gradient again.','That doubles the normalization reduction and changes the velocity-product torque.'),('Remove Ḣq̇ because the one-half already accounts for all configuration dependence.','Ḣq̇ arises from the time derivative of momentum and remains required.'),('Replace the potential gradient by V itself to compensate for the doubled T.','Potential and generalized gravity force have different roles.')],difficulty='medium',forms=[FE,FK],conflict='The equation page calls q̇ᵀHq̇ kinetic energy without the physical factor one-half; its −½∇T term is consistent only when T denotes twice physical kinetic energy.',evidence=['delan'])
add([(1765,'figure','Kinetic-energy definition and velocity-product subtraction block.','conflict')],'flow-factor','Flowchart factor discrepancy','The flowchart defines T=½q̇ᵀHq̇ and subtracts ½∇T in its velocity-product block. What correction follows from the Euler–Lagrange equation?', [('With T already physical kinetic energy, subtract ∇T, not ½∇T.','The one-half is already included in T, so halving its gradient again is erroneous.'),('Keep ½∇T and double the potential gradient instead.','That changes gravity rather than correcting the kinetic derivative.'),('Keep ½∇T and omit Ḣq̇.','This loses another required contribution rather than fixing the factor.'),('Replace the subtraction by +∇T while retaining the rest of the flowchart.','The configuration derivative of kinetic energy enters with a minus sign.')],difficulty='medium',forms=[FE],conflict='Unlike p1764, the p1765 flowchart includes one-half inside T and again before its gradient, creating a factor-of-two error.',evidence=['delan'])
add([(1764,'equation','Ḣq̇ and kinetic/potential gradient terms.','premise'),(1765,'figure','Derivative branches to torque summation.','conflict')],'lagrangian-calc','Integrated scalar Euler–Lagrange check','In an added one-joint model, H(q)=1+q² kg·m² and V(q)=2q J, with q treated as a dimensionless radian measure. At q=1, q̇=2 rad/s and q̈=3 rad/s², use physical K=½Hq̇². What torque is Hq̈+Ḣq̇−∂K/∂q+∂V/∂q?', [('12 N·m.','The four terms are 6, 8, −4 and 2, which sum to 12.'),('14 N·m.','This halves the already normalized kinetic gradient a second time.'),('8 N·m.','This omits the kinetic-gradient subtraction but also omits Ḣq̇, retaining only inertia and potential.'),('20 N·m.','This adds the kinetic gradient rather than subtracting it.')],typ='numerical',difficulty='medium',forms=[FE,formula('H=1+q²; V=2q; Ḣ=2qq̇; ∂K/∂q=q q̇²',{'H':'added scalar inertia in kg·m²','V':'added potential in J','q':'joint angle expressed as dimensionless radian measure','q̇':'angular velocity','K':'physical kinetic energy ½Hq̇²','Ḣ':'inertia time derivative'},{'H':'kg·m²','V,K':'J','q':'rad, treated as dimensionless','q̇':'rad/s','Ḣ':'kg·m²/s'},['Numerical coefficients carry the compatible SI units; added exercise, not the source 2R system.'])],steps=['H=2 and Ḣ=2×1×2=4.','Hq̈=6, Ḣq̇=8, ∂K/∂q=1×2²=4 and ∂V/∂q=2.','Sum 6+8−4+2=12.'],assumptions=['Explicit added scalar model; source flowchart factor is corrected using the physical energy convention.'],conflict='The p1765 half-gradient defect would give 14 rather than 12 for this added test.',evidence=['delan'])
add([(1764,'equation','Time derivative of configuration-dependent H.','premise')],'chain-rule','Configuration-dependent inertia derivative','For H=H(q1,q2) without explicit time dependence, which expression is the total Ḣ along a trajectory?', [('(∂H/∂q1)q̇1+(∂H/∂q2)q̇2.','The chain rule sums each configuration derivative weighted by its joint velocity.'),('(∂H/∂q1)q̈1+(∂H/∂q2)q̈2.','This substitutes acceleration for the first time derivative of position.'),('∂H/∂q1+∂H/∂q2 without velocity factors.','That omits the rate at which each coordinate changes.'),('Hq̇, interpreted as a matrix derivative.','Hq̇ is a momentum vector, not the matrix time derivative.')],forms=[FE])
add([(1765,'figure','Green potential path and gradient contribution to torque.')],'potential-gradient','Potential branch of the flowchart','Which operation turns the scalar potential-network output V(q) into gravity-compensation torque?', [('The configuration gradient ∇qV.','Potential changes per joint displacement supply generalized gravity-compensation forces.'),('The scalar value V multiplied by the velocity vector.','This is not the potential gradient.'),('The velocity gradient ∂V/∂q̇ in this position-only potential model.','It vanishes for V(q) and does not supply gravity.'),('The inverse of V treated as a mass matrix.','A scalar potential is not an inertia matrix.')],typ='diagram',forms=[FG,FK])
add([(1766,'statement','5000 versus 50000 samples and structured-versus-black-box comparison.')],'data-efficiency','Interpreting the sample-count comparison','What is justified by the source’s 5,000-sample DeLaN and 50,000-sample MLP examples?', [('They illustrate a possible data-efficiency benefit in the reported setup, not a universal tenfold reduction for every task.','Architecture, training, seeds and evaluation conditions must be controlled before generalizing the comparison.'),('Exactly one tenth of the data is sufficient for any robot with the same number of joints.','Joint count alone does not fix the learning difficulty or coverage requirements.'),('The two methods use identical data and differ only in the plotting colors.','The displayed dataset sizes and model structures differ.'),('The smaller training set proves that the test torque values were never used in any model selection.','Sample counts alone do not establish the model-selection protocol.')],typ='scenario',conflict='The example frames the smaller dataset as improved sample efficiency; its figures alone do not establish a universal tenfold guarantee or a fully controlled comparison.')
