add([(1768,'code','Sequential training/test slices after random sampling.')],'aligned-slices','Preserving label alignment','Why must Q, DQ, DDQ and TAU use the same row indices when splitting or shuffling?', [('Each torque row was generated from the matching position, velocity and acceleration rows.','Independent reordering would pair features with torque labels from different states.'),('Matching indices force all four arrays to contain identical numerical values.','Alignment preserves correspondence, not equal values.'),('Torque labels can be shuffled independently because the model predicts a distribution.','This is state-conditioned supervised regression, not an unpaired distribution task.'),('Only Q and TAU need alignment because velocity and acceleration do not enter the torque.','The complete inverse dynamics depends on all three state arrays.')],typ='code')
