add([(1769,'code','MSELoss and Adam learning rate/weight decay settings.')],'loss-regression','Loss for two torque outputs','For an added batch with prediction-minus-target error matrix [[1,−1],[2,−2]] N·m, what does default mean-reduced MSELoss return?', [('2.5 (N·m)².','The four squared errors sum to 10 and are averaged over four elements.'),('5 (N·m)².','This divides by two rows but not by the two output components.'),('√2.5 N·m.','That is RMSE, not the mean-squared training loss.'),('1.5 N·m.','That is the mean absolute error.')],typ='numerical',forms=[formula('MSE=(1/(BJ))ΣbΣj e_bj²',{'MSE':'mean-squared error over all batch/output elements','B':'batch row count','J':'output count','e_bj':'prediction-minus-target torque error for row b and joint j','b,j':'row and joint indices'},{'MSE':'(N·m)²','e_bj':'N·m','B,J,b,j':'dimensionless counts/indices'},['Default mean reduction over both dimensions; added error matrix.'])],steps=['Square entries to obtain 1,1,4,4.','Sum 10 and divide by four elements.'],evidence=['mse'])
