add([(1771,'code','model.eval and with torch.enable_grad followed by detach.')],'inference-grad','Why gradient recording remains enabled','Why can the structured predictor use model.eval() and torch.enable_grad() together?', [('eval changes relevant module behavior, while gradient recording is still needed to form derivatives of learned energies.','Evaluation mode is separate from autograd; computing physical derivatives can require recording during prediction.'),('eval automatically disables all gradient recording, and enable_grad merely prints a warning.','eval does not itself disable autograd.'),('enable_grad automatically performs optimizer updates during evaluation.','Recording gradients is not an optimizer step.'),('eval computes the torque RMSE and therefore makes derivatives unnecessary.','eval only changes module mode; explicit prediction and metric code still run.')],typ='code',evidence=['autograd','enable'])
add([(1771,'code','Prediction returns detached torque and later converts to NumPy.'),(1772,'code','predict(...).numpy() on trajectory tensors.')],'detach-cpu','Autograd boundary and NumPy conversion','For a detached prediction tensor on a GPU in an added deployment, what extra step is needed before NumPy conversion?', [('Move it to CPU, then call numpy; detaching alone does not change its device.','The source creates CPU tensors, but a GPU variant must explicitly transfer the detached result to CPU.'),('Call eval again to move all values to CPU.','eval changes module mode, not device placement.'),('Remove detach and convert the gradient-tracking GPU tensor directly.','That does not solve the device or gradient-tracking boundary.'),('Convert every torque to an integer class before calling numpy.','Torque regression values need not become integer labels.')],typ='code',assumptions=['Added GPU deployment qualification; the printed example uses CPU tensors.'],evidence=['autograd','numpy'])
add([(1761,'code','Printed MLP shoulder RMSE.'),(1771,'code','Printed DeLaN shoulder RMSE.')],'reported-improvement','Reported shoulder error reduction','Using only the reported shoulder RMSE values 0.6311 and 0.2826 N·m, what is the relative reduction from MLP to DeLaN?', [('Approximately 55.22%.','(0.6311−0.2826)/0.6311×100≈55.22%.'),('Approximately 44.78%.','This is the remaining DeLaN/MLP error percentage, not the reduction.'),('Approximately 123.32%.','This divides the reduction by the new value instead of the baseline.'),('34.85%.','This treats the absolute difference 0.3485 as a percentage without dividing by the baseline.')],typ='numerical',forms=[formula('r=100(E_old−E_new)/E_old',{'r':'relative error reduction','E_old':'baseline RMSE','E_new':'comparison RMSE'},{'r':'percent','E_old,E_new':'N·m'},['Positive nonzero baseline; arithmetic on reported values only, not a reproduced or universal performance claim.'])],steps=['Difference=0.3485 N·m.','Divide by 0.6311 and multiply by 100.'],assumptions=['Use the reported values; differing training setups prevent a universal causal conclusion.'])
add([(1772,'code','Sinusoidal q1,q2 and their first and second derivatives.')],'trajectory-derivatives','Differentiate the elbow trajectory','For the printed q2(t)=0.5 sin(2t), with t in seconds and the sinusoid argument understood in radians, which velocity/acceleration pair is correct?', [('q̇2=cos(2t), q̈2=−2 sin(2t).','Each derivative brings a factor of 2 from the inner argument.'),('q̇2=0.5 cos(2t), q̈2=−0.5 sin(2t).','This omits both chain-rule factors.'),('q̇2=cos(2t), q̈2=−sin(2t).','This omits the second chain-rule factor.'),('q̇2=2 cos(2t), q̈2=−4 sin(2t).','This drops the original amplitude factor 0.5.')],typ='derivation',forms=[formula('q=A sin(ωt); q̇=Aω cos(ωt); q̈=−Aω² sin(ωt)',{'q':'joint angle','q̇,q̈':'angular velocity and acceleration','A':'angle amplitude','ω':'angular frequency','t':'time'},{'q,A':'rad','q̇':'rad/s','q̈':'rad/s²','ω':'rad/s with radian argument dimensionless','t':'s'},['Added symbolic notation for the printed sinusoid; no phase offset.'])],steps=['Differentiate once using Aω=0.5×2=1.','Differentiate again using −Aω²=−0.5×4=−2.'])
