add([(1772,'code','Complete sinusoidal trajectory and inverse_dynamics reference call.'),(1758,'code','Unit-parameter torque function.')],'trajectory-start','Torque at the start of the test path','At t=0 on the printed sinusoidal path, what reference torque does the unit-parameter source model give?', [('(29.43,9.81) N·m.','q=(0,0), q̇=(1,1), q̈=(0,0); sin q2=0 makes C zero, leaving G.'),('(36.43,12.81) N·m.','This incorrectly treats the nonzero velocities (1,1) as accelerations, adding inertia torque (7,3).'),('(0,0) N·m.','Zero acceleration does not remove gravity torque.'),('(−29.43,−9.81) N·m.','This reverses the gravity-compensation sign.')],typ='numerical',difficulty='medium',forms=[FM,FC,FG],steps=['Evaluate the sine/cosine path at t=0.','Acceleration and h vanish; gravity is (3g,g).'])
