add([(1774,'statement','Physical consistency and energy-conservation claim.','conflict')],'energy-balance','Forced versus conserved energy','For the time-invariant conservative model driven by actuator torque, which statement correctly qualifies energy conservation?', [('d(K+V)/dt=τᵀq̇; total energy is conserved when net applied power is zero, not for arbitrary powered motion.','The learned conservative structure yields a work–energy balance; actuator work can change total energy.'),('K+V is constant for every applied torque because H is positive definite.','Positive inertia does not cancel actuator power.'),('Only potential energy is conserved while kinetic energy can change independently.','The mechanical balance concerns their sum.'),('Energy increases at a rate equal to τ alone, independent of velocity.','Power is torque paired with angular velocity, not torque alone.')],forms=[FE,formula('E=K+V; Ė=τᵀq̇',{'E':'total mechanical energy','K,V':'physical kinetic and potential energy','Ė':'time rate of mechanical energy','τ':'net applied generalized torque not already represented by potential','q̇':'joint angular velocity vector'},{'E,K,V':'J','Ė':'W','τ':'N·m','q̇':'rad/s'},['Time-invariant conservative inertia/potential model, no unmodelled dissipation; zero net power gives constant E.'])],conflict='The summary’s energy-conservation wording needs an unforced or zero-net-power qualification; powered or dissipative motion is not generally constant-energy.',evidence=['delan'])
add([(1774,'statement','Physics-based modelling, parameter dependence and future models.')],'model-selection','Nominal model plus learned residual','An added deployment has a reliable rigid-body model but repeatable speed-dependent friction absent from its equations. Which design directly targets that missing effect without discarding the known dynamics?', [('Keep the rigid-body torque and learn an explicitly defined friction/residual correction from appropriate measured data.','This preserves the known nominal structure while addressing a specified unmodelled contribution.'),('Refit only the potential V(q) and require it to represent friction that changes sign with velocity.','A position-only conservative potential cannot generally encode velocity-dependent dissipation.'),('Treat the residual torque as extra joint position and feed it through the unchanged kinematic map.','That changes variable roles rather than modelling the missing force.'),('Remove all velocity inputs because the rigid-body matrix already depends on position.','The targeted friction effect explicitly depends on velocity.')],typ='scenario',difficulty='medium',forms=[FD],assumptions=['Added residual-design scenario; actual deployment still needs validation and safe operating constraints.'])

